import{_ as e,o,c as t,a7 as i}from"./chunks/framework.FWlv_suP.js";const f=JSON.parse('{"title":"Who Called Terms and Conditions","description":"Official Terms and Conditions for Who Called.","frontmatter":{"title":"Who Called Terms and Conditions","description":"Official Terms and Conditions for Who Called.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"terms/who-called.md","filePath":"terms/who-called.md"}'),n={name:"terms/who-called.md"};function r(s,a,l,d,c,p){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="terms-and-conditions-for-who-called" tabindex="-1">Terms and Conditions for Who Called <a class="header-anchor" href="#terms-and-conditions-for-who-called" aria-label="Permalink to &quot;Terms and Conditions for Who Called&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 3, 2026</p><h2 id="use-of-who-called" tabindex="-1">Use of Who Called <a class="header-anchor" href="#use-of-who-called" aria-label="Permalink to &quot;Use of Who Called&quot;">​</a></h2><p>Who Called is provided as a personal contact, call-history viewing, number-tag, saved-message, and communication-launching tool. You are responsible for the accuracy and lawful use of information you enter, import, or view.</p><p>Keepsake views and reminders are organizational aids. You are responsible for the accuracy of birthday and anniversary dates and for deciding whether a notification is appropriate for your device and lock screen.</p><p>The app does not identify unknown callers through a public database, guarantee caller identity, record calls, place calls automatically, or send SMS or WhatsApp messages automatically.</p><h2 id="contact-and-call-information" tabindex="-1">Contact and call information <a class="header-anchor" href="#contact-and-call-information" aria-label="Permalink to &quot;Contact and call information&quot;">​</a></h2><p>You are responsible for having an appropriate basis to store another person&#39;s contact details, notes, messages, or call information and for complying with applicable privacy, communications, and recording laws.</p><h2 id="external-services" tabindex="-1">External services <a class="header-anchor" href="#external-services" aria-label="Permalink to &quot;External services&quot;">​</a></h2><p>Calls, SMS drafts, and WhatsApp chats are completed by external applications and services. Review recipients and message content before continuing. Their terms, availability, charges, and privacy practices apply.</p><p>Web links detected in saved messages are opened by an external browser only after confirmation. Review the destination before continuing. The developer does not control or endorse external websites.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Android reminder delivery depends on notification permission, device settings, battery optimization, time-zone changes, and operating-system scheduling. A reminder may be delayed, suppressed, or unavailable, and should not be relied on for emergencies, legal deadlines, medication, payments, or other time-critical purposes.</p><h2 id="security-and-files" tabindex="-1">Security and files <a class="header-anchor" href="#security-and-files" aria-label="Permalink to &quot;Security and files&quot;">​</a></h2><p>You are responsible for securing your device and protecting PINs, backup passphrases, and exported files. The developer cannot recover forgotten PINs or backup passphrases. CSV and vCard exports are readable and should be stored and shared carefully.</p><h2 id="acceptable-use" tabindex="-1">Acceptable use <a class="header-anchor" href="#acceptable-use" aria-label="Permalink to &quot;Acceptable use&quot;">​</a></h2><p>Do not misuse the app for harassment, spam, impersonation, unlawful monitoring, or violation of another person&#39;s rights.</p><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Features and compatibility may change as Who Called is improved. The app is provided without a guarantee that it will always be available, error-free, or suitable for every purpose.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions about these terms can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',21)])])}const u=e(n,[["render",r]]);export{f as __pageData,u as default};
